static Report report(List<Batch> batches) {
    List<Payment> payments = batches.stream().flatMap(b -> b.payments().stream()).toList();
    Map<String, Payment> byId = payments.stream()
            .collect(Collectors.toMap(Payment::id, p -> p));            // throws on a repeated id

    List<Payment> settled = payments.stream().filter(p -> p.status() == SETTLED).toList();
    return new Report(
            payments.size(),
            settled.stream().mapToLong(Payment::amountCents).sum(),
            payments.stream().map(Payment::refundCents).filter(Objects::nonNull)
                    .mapToLong(Long::longValue).sum(),
            settled.stream().collect(Collectors.groupingBy(Payment::merchant,
                    LinkedHashMap::new,                                   // or no order is promised
                    Collectors.summingLong(p -> p.amountCents() - refundOf(p)))),
            payments.stream().filter(p -> p.status() == FAILED).map(Payment::id).toList(),
            settled.stream().max(Comparator.comparingLong(Payment::amountCents)));   // Optional<Payment>
}

kotlin.src:
fun report(batches: List<Batch>): Report {
    val payments = batches.flatMap { it.payments }
    val repeated = payments.groupingBy { it.id }.eachCount().filterValues { it > 1 }.keys
    require(repeated.isEmpty()) { "duplicate payment ids: ${repeated.joinToString()}" }   // associateBy would not

    val settled = payments.filter { it.status == SETTLED }
    return Report(
        paymentCount = payments.size,
        settledCents = settled.sumOf { it.amountCents },
        refundedCents = payments.mapNotNull { it.refundCents }.sum(),
        netByMerchant = settled.groupBy { it.merchant }                      // first-seen order
            .mapValues { (_, ps) -> ps.sumOf { it.amountCents - (it.refundCents ?: 0L) } },
        failedIds = payments.filter { it.status == FAILED }.map { it.id },
        largestSettled = settled.maxByOrNull { it.amountCents },            // Payment?, null when none
    )
}

